<?php if(!$receipt): ?><p class="empty panel">Comprobante no encontrado.</p><?php else: ?><article class="panel receipt"><?php view('components/brand'); ?><span class="eyebrow">YASIG ODONT · FAMILY DENTAL CARE</span><h2>Comprobante interno</h2><p class="notice warning">No es una factura tributaria.</p><dl><dt>Número</dt><dd><?= e($receipt['number']) ?></dd><dt>Paciente</dt><dd><?= e($receipt['patient']) ?></dd><dt>Plan</dt><dd><?= e($receipt['plan']) ?></dd><dt>Importe</dt><dd><?= money($receipt['amount']) ?></dd><dt>Método</dt><dd><?= e(label($receipt['method'])) ?></dd><dt>Fecha</dt><dd><?= local_date($receipt['created_at']) ?></dd><dt>Estado</dt><dd><?= $receipt['voided_at'] ? 'ANULADO · '.e($receipt['void_reason']):'Registrado' ?></dd></dl><?php if(flag('APP_DEMO')): ?><p>ENTORNO DE DEMOSTRACIÓN — DATOS FICTICIOS</p><?php endif; ?><button class="button" data-print>Imprimir comprobante</button></article><?php endif; ?>
